// Window = the last 7 days ending on the most recent Friday 19:00 (Paris time).
// A 5-minute tolerance absorbs trigger jitter, so a run at 18:59:59 still anchors on today.
// oldest/latest are ISO dates: the Slack node converts them to Slack timestamps itself.
const now = DateTime.now().setZone('Europe/Paris');
const reference = now.plus({ minutes: 5 });
let end = reference.set({ hour: 19, minute: 0, second: 0, millisecond: 0 });
while (end.weekday !== 5 || end > reference) {
  end = end.minus({ days: 1 }).set({ hour: 19, minute: 0, second: 0, millisecond: 0 });
}
const start = end.minus({ weeks: 1 });

return [{
  json: {
    oldest: start.toISO(),
    latest: end.toISO(),
    periodStart: start.toFormat('dd/MM/yyyy HH:mm'),
    periodEnd: end.toFormat('dd/MM/yyyy HH:mm'),
    subject: 'Synthèse Slack, semaine du ' + now.toFormat('dd/MM'),
  },
}];

// Turns raw Slack history of the general channel into a readable, chronological transcript.
// A Slack failure arrives here as an item carrying an "error" field (the Slack node continues on
// its regular output). It is rethrown once, so a single retry loop starts per attempt.
const items = $input.all();

const failures = items
  .map((item) => item.json && item.json.error)
  .filter(Boolean)
  .map((err) => (typeof err === 'string' ? err : err.message || JSON.stringify(err)));
if (failures.length) {
  throw new Error('Slack read failed: ' + [...new Set(failures)].join(' | '));
}

const IGNORED_SUBTYPES = ['channel_join', 'channel_leave', 'channel_purpose', 'channel_topic', 'channel_name', 'channel_archive', 'channel_unarchive'];

const lines = items
  .map((item) => item.json)
  .filter((m) => m && typeof m.text === 'string' && m.text.trim() !== '' && !IGNORED_SUBTYPES.includes(m.subtype))
  .sort((a, b) => Number(a.ts) - Number(b.ts))
  .map((m) => {
    const when = DateTime.fromSeconds(Number(m.ts)).setZone('Europe/Paris').setLocale('fr').toFormat('ccc dd/MM HH:mm');
    const profile = m.user_profile || {};
    const author = profile.real_name || profile.display_name || m.username || (m.user ? '<@' + m.user + '>' : 'bot');
    return '[' + when + '] ' + author + ' : ' + m.text.replace(/\s+/g, ' ').trim();
  });

return [{
  json: {
    hasMessages: lines.length > 0,
    generalCount: lines.length,
    generalTranscript: lines.join('\n'),
  },
}];

// Parses the Gemini JSON answer and renders the HTML email body.
// Any unreadable answer throws, which routes to the retry loop.
const period = $('Compute Period').first().json;
const res = $input.first().json;

let summary = null;
if (res && typeof res.general === 'string') {
  summary = res;
} else {
  let raw = '';
  if (res && res.content && Array.isArray(res.content.parts)) {
    raw = res.content.parts.map((p) => (typeof p.text === 'string' ? p.text : '')).join('');
  } else if (res && typeof res.text === 'string') {
    raw = res.text;
  }
  raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    summary = JSON.parse(raw);
  } catch (e) {
    throw new Error('Gemini returned an unreadable answer: ' + raw.slice(0, 300));
  }
}
if (!summary || typeof summary.general !== 'string' || !summary.general.trim()) {
  throw new Error('Gemini answer is missing the summary.');
}

const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toParagraphs = (s) => escapeHtml(s.trim())
  .split(/\n\s*\n/)
  .map((p) => '<p>' + p.trim().replace(/\n/g, '<br>') + '</p>')
  .join('');

const html = '<p><em>Période couverte : du ' + period.periodStart + ' au ' + period.periodEnd + ' (heure de Paris).</em></p>'
  + '<h2>#général</h2>' + toParagraphs(summary.general);

return [{ json: { subject: period.subject, html } }];

// Builds the "nothing to report" email when the general channel was silent.
const period = $('Compute Period').first().json;
const html = '<p><em>Période couverte : du ' + period.periodStart + ' au ' + period.periodEnd + ' (heure de Paris).</em></p>'
  + '<p>Rien à signaler cette semaine : aucun message n\u2019a été publié dans #général.</p>';

return [{ json: { subject: period.subject, html } }];

// Counts consecutive failures in this execution ($runIndex is 0 on the first failure)
// and keeps the error message for the alert email.
const input = $input.first().json || {};
const err = input.error;
let errorMessage = 'Unknown error';
if (typeof err === 'string') errorMessage = err;
else if (err && (err.message || err.description)) errorMessage = [err.message, err.description].filter(Boolean).join(' - ');
else errorMessage = JSON.stringify(input).slice(0, 500);

return [{ json: { failureCount: $runIndex + 1, errorMessage } }];
